package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertThrows;

import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.junit.jupiter.api.Test;

class GqlResourceLimitTest {

	private final GQLParser parser = new GQLParser();

	@Test
	void rejectsAPathBeforeItsAlgebraCanOverflowTheJavaStack() {
		String query = "MATCH (n)" + "-[:`urn:p`]->()".repeat(3_000) + " RETURN n";
		assertThrows(MalformedQueryException.class, () -> visit(query));
	}

	@Test
	void rejectsTooManyUnionBranchesBeforeAlgebraVisitorsOverflow() {
		String query = "RETURN 1 AS value" + " UNION ALL RETURN 1 AS value".repeat(4_000);
		assertThrows(MalformedQueryException.class, () -> visit(query));
	}

	@Test
	void rejectsTooManyComputedColumnsBeforeAlgebraVisitorsOverflow() {
		StringBuilder query = new StringBuilder("RETURN 0 AS column0");
		for (int i = 1; i < 4_000; i++) {
			query.append(", ").append(i).append(" AS column").append(i);
		}
		assertThrows(MalformedQueryException.class, () -> visit(query.toString()));
	}

	private void visit(String query) {
		parser.parseQuery(query, null).getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
		});
	}
}
